    Qsh0  : forall a, (2147450880 + (bv_unsigned sp - 4096) / 8 <= a < 2147450880 + bv_unsigned sp / 8)%Z ->
              mem (Z_to_bv 64 a) = Some (Z_to_bv 8 0) }.

